  $('#urlInput').value=item?.url||''; $('#titleInput').value=item?.title||''; $('#noteInput').value=item?.note||''; $('#collectionInput').value=item?.collection||'Design'; $('#tagsInput').value=item?.tags.join(', ')||''; dialog.showModal(); setTimeout(()=>$('#urlInput').focus(),50);
}
